mapper.select:
SELECT DISTINCT a.warn_id, a.instance_id, a.warn_content, a.warn_time, d.device_mete_id, d.custom_id, e.device_id, a.device_mete_name, d.custom_name, a.device_name, e.device_type, a.device_type_name, a.warn_type, a.warn_level, a.one_cruise_device_name, a.two_cruise_device_name, a.three_cruise_device_name AS threeCruiseDeviceName FROM t_cruise_nonhomologous_warn a LEFT JOIN t_std_devicemete d ON d.device_mete_id = a.device_mete_id LEFT JOIN t_std_device e ON e.device_id = d.device_id WHERE 1 = 1 and a.instance_id = #{instanceId, jdbcType=BIGINT} and e.device_type = #{deviceType, jdbcType=INTEGER} and e.device_name like concat( '%',#{deviceName, jdbcType=VARCHAR},'%') and d.mete_name like concat('%',#{deviceMeteName, jdbcType=VARCHAR},'%')
and a.warn_type = #{warnType, jdbcType=INTEGER}
and a.warn_time between #{startTime,jdbcType=TIMESTAMP} and #{endTime,jdbcType=TIMESTAMP}
ORDER BY a.warn_time DESC
